def bounds(
    self,
) -> tuple[
    tuple[Version, bool] | None, tuple[Version, bool] | None
]:
    """Return the combined lower and upper bounds of all specifiers.

    Returns a ``(lower, upper)`` tuple.  Each element is either
    ``None`` (no bound) or ``(Version, inclusive: bool)``.

    >>> SpecifierSet(">=1.0,<2.0").bounds()
    ((<Version('1.0')>, True), (<Version('2.0')>, False))
    >>> SpecifierSet("==1.0").bounds()
    ((<Version('1.0')>, True), (<Version('1.0')>, True))
    >>> SpecifierSet("~=1.4.5").bounds()
    ((<Version('1.4.5')>, True), (<Version('1.5')>, False))
    >>> SpecifierSet("").bounds()
    (None, None)

    .. versionadded:: 26.4
    """
    if self._has_arbitrary:
        raise ValueError("bounds() does not support === specifiers")

    if not self._specs:
        return (None, None)

    lower_ver: Version | None = None
    lower_inc: bool = False
    upper_ver: Version | None = None
    upper_inc: bool = False

    for spec in self._specs:
        op, ver_str = spec._spec
        version = spec._require_spec_version()

        if ver_str.endswith(".*"):
            # ==V.*
            if op == "==":
                new_lower: tuple[Version, bool] | None = (version, True)
                new_upper: tuple[Version, bool] | None = (
                    _next_prefix_dev0(version),
                    False,
                )
            else:
                # !=V.* – no simple bounds
                continue
        elif op == "~=":
            prefix = version.__replace__(release=version.release[:-1])
            new_lower = (version, True)
            new_upper = (_next_prefix_dev0(prefix), False)
        elif op == ">=":
            new_lower = (version, True)
            new_upper = None
        elif op == ">":
            new_lower = (version, False)
            new_upper = None
        elif op == "<=":
            new_lower = None
            new_upper = (version, True)
        elif op == "<":
            new_lower = None
            new_upper = (version, False)
        elif op == "==":
            new_lower = (version, True)
            new_upper = (version, True)
        elif op == "!=":
            continue
        else:
            continue  # pragma: no cover

        # Merge lower bound – pick the larger version; equal → exclusive wins
        if new_lower is not None:
            if lower_ver is None:
                lower_ver, lower_inc = new_lower
            else:
                if new_lower[0] > lower_ver:
                    lower_ver, lower_inc = new_lower
                elif new_lower[0] == lower_ver and not lower_inc:
                    lower_inc = False

        # Merge upper bound – pick the smaller version; equal → exclusive wins
        if new_upper is not None:
            if upper_ver is None:
                upper_ver, upper_inc = new_upper
            else:
                if new_upper[0] < upper_ver:
                    upper_ver, upper_inc = new_upper
                elif new_upper[0] == upper_ver and not upper_inc:
                    upper_inc = False

    return (
        (lower_ver, lower_inc) if lower_ver is not None else None,
        (upper_ver, upper_inc) if upper_ver is not None else None,
    )
